def predict_iter(g, back, iters=5):
    R,C=len(g),len(g[0])
    out=[row[:] for row in g]
    for _ in range(iters):
        new=[row[:] for row in out]
        for r in range(R):
            pos=[c for c in range(C) if out[r][c]!=back]
            for a,b in zip(pos,pos[1:]):
                for c in range(a+1,b): new[r][c]=3
        for c in range(C):
            pos=[r for r in range(R) if out[r][c]!=back]
            for a,b in zip(pos,pos[1:]):
                for r in range(a+1,b): new[r][c]=3
        if new==out: break
        out=new
    return out
